/**
 * AI Documentation Tools
 *
 * Tools for searching Breeze documentation content.
 * - search_documentation (Tier 1): Search how-to guides, feature docs, and reference material
 *
 * The index (`../data/docsIndex.json`, generated by `scripts/build-docs-index.ts`)
 * carries each page's `##`/`###` sections with their body text, so a search
 * returns the passage that answers the question rather than only page titles
 * and headings (#10398).
 */

import docsIndex from '../data/docsIndex.json';
import type { AiTool, AiToolTier } from './aiTools';

type DocsSection =
  | 'getting-started'
  | 'deploy'
  | 'agents'
  | 'security'
  | 'features'
  | 'monitoring'
  | 'reference';

export interface DocsIndexSection {
  /** Raw heading text; '' for the intro before the first heading. */
  heading: string;
  /** Rendered heading id; '' for the intro. */
  anchor: string;
  text: string;
}

export interface DocsIndexEntry {
  path: string;
  title: string;
  description: string;
  headings: string[];
  section: DocsSection | (string & {});
  sections: DocsIndexSection[];
}

const DOCS_BASE_URL = 'https://docs.breezermm.com';
const MAX_PAGES = 5;
const MAX_EXCERPTS = 3;
const MAX_EXCERPTS_PER_PAGE = 2;
const MAX_EXCERPT_CHARS = 2_000;
const MAX_KEY_TOPICS_CHARS = 240;
/** Whole-result cap; well under the chat tool-result budget (MAX_TOOL_RESULT_CHARS) after JSON escaping. */
export const DOCS_SEARCH_MAX_CHARS = 6_000;

/** Words that appear on nearly every page and would otherwise make every page "match". */
const STOPWORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'can', 'do', 'does', 'for', 'from', 'how', 'i', 'if',
  'in', 'is', 'it', 'its', 'me', 'my', 'of', 'on', 'or', 'should', 'so', 'that', 'the', 'their', 'this',
  'to', 'was', 'we', 'what', 'when', 'where', 'which', 'who', 'why', 'will', 'with', 'you', 'your',
]);

const typedDocsIndex = docsIndex as DocsIndexEntry[];

if (!Array.isArray(typedDocsIndex) || typedDocsIndex.length === 0) {
  console.error('[AI Docs] docsIndex.json is empty or invalid — search_documentation will not return results');
}

/** Lowercased query terms with filler words dropped and a trailing plural `s` trimmed (substring match covers both forms). */
function toKeywords(rawQuery: string): string[] {
  const words = rawQuery
    .toLowerCase()
    .split(/\s+/)
    .map((word) => word.replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, ''))
    .filter(Boolean);
  const meaningful = words.filter((word) => !STOPWORDS.has(word));
  const chosen = meaningful.length > 0 ? meaningful : words;
  const stemmed = chosen.map((word) => (word.length > 3 && word.endsWith('s') && !word.endsWith('ss') ? word.slice(0, -1) : word));
  return [...new Set(stemmed)];
}

interface SectionHit {
  page: DocsIndexEntry;
  pageRank: number;
  section: DocsIndexSection;
  order: number;
  coverage: number;
  score: number;
}

function scoreSections(candidates: DocsIndexEntry[], keywords: string[]): SectionHit[] {
  const hits: SectionHit[] = [];
  candidates.forEach((page, pageRank) => {
    const pageText = `${page.title} ${page.description}`.toLowerCase();
    // A page with no body still matches on its title/description.
    const sections = page.sections.length > 0 ? page.sections : [{ heading: '', anchor: '', text: '' }];
    sections.forEach((section, order) => {
      const heading = section.heading.toLowerCase();
      const body = section.text.toLowerCase();
      let coverage = 0;
      let score = 0;
      for (const keyword of keywords) {
        const inHeading = heading.includes(keyword);
        const inPage = pageText.includes(keyword);
        const inBody = body.includes(keyword);
        if (inHeading || inPage || inBody) coverage += 1;
        score += (inHeading ? 3 : 0) + (inPage ? 2 : 0) + (inBody ? 1 : 0);
      }
      // Each distinct keyword found is worth 2, on top of where it was found
      // (heading 3, page title/description 2, body 1). Coverage is not ranked
      // first on its own: a stray substring in a huge reference table would
      // then beat a page whose title and heading both match.
      if (coverage > 0) hits.push({ page, pageRank, section, order, coverage, score: score + 2 * coverage });
    });
  });

  return hits.sort((left, right) => (
    right.score - left.score
    || right.coverage - left.coverage
    || left.page.title.localeCompare(right.page.title)
    || left.pageRank - right.pageRank
    || left.order - right.order
  ));
}

const PAGE_SEPARATOR = '\n\n---\n\n';
const BLOCK_SEPARATOR = '\n\n';
/** Worst case for the leading `…\n\n` plus trailing `\n\n…` markers. */
const ELLIPSIS_CHARS = 6;

/** The section text when it fits; otherwise the paragraphs around the best-matching one, marked with `…`. */
function excerpt(text: string, keywords: string[], budget: number): string {
  if (text.length <= budget) return text;

  const paragraphs = text.split(/\n{2,}/);
  const sizeOf = (index: number) => paragraphs[index]?.length ?? 0;
  let best = 0;
  let bestHits = -1;
  paragraphs.forEach((paragraph, index) => {
    const lower = paragraph.toLowerCase();
    const hits = keywords.filter((keyword) => lower.includes(keyword)).length;
    if (hits > bestHits) {
      best = index;
      bestHits = hits;
    }
  });

  let start = best;
  let end = best;
  let length = sizeOf(best);
  if (length + ELLIPSIS_CHARS > budget) {
    // One paragraph (a long table or code block) is bigger than the budget:
    // window it so the first keyword hit sits near the top.
    const paragraph = paragraphs[best] ?? '';
    const lower = paragraph.toLowerCase();
    const hitAt = Math.min(...keywords.map((keyword) => lower.indexOf(keyword)).filter((at) => at >= 0), paragraph.length);
    const width = Math.max(0, budget - ELLIPSIS_CHARS);
    const from = Math.max(0, Math.min(hitAt - Math.floor(width / 4), paragraph.length - width));
    const to = from + width;
    return `${from > 0 ? '…' : ''}${paragraph.slice(from, to)}${to < paragraph.length ? '…' : ''}`;
  }
  // Grow forward first (answers usually follow the matching lead-in), then back.
  let grew = true;
  while (grew) {
    grew = false;
    if (end + 1 < paragraphs.length && length + 2 + sizeOf(end + 1) + ELLIPSIS_CHARS <= budget) {
      end += 1;
      length += 2 + sizeOf(end);
      grew = true;
    }
    if (start > 0 && length + 2 + sizeOf(start - 1) + ELLIPSIS_CHARS <= budget) {
      start -= 1;
      length += 2 + sizeOf(start);
      grew = true;
    }
  }

  const body = paragraphs.slice(start, end + 1).join('\n\n');
  return `${start > 0 ? '…\n\n' : ''}${body}${end < paragraphs.length - 1 ? '\n\n…' : ''}`;
}

function pageUrl(page: DocsIndexEntry, anchor = ''): string {
  return `${DOCS_BASE_URL}${page.path}${anchor ? `#${anchor}` : ''}`;
}

function keyTopics(page: DocsIndexEntry): string {
  const joined = page.headings.join(', ');
  return joined.length <= MAX_KEY_TOPICS_CHARS ? joined : `${joined.slice(0, MAX_KEY_TOPICS_CHARS - 1)}…`;
}

/**
 * Searches the docs index and renders up to MAX_PAGES pages, with the text of
 * the best-matching sections (MAX_EXCERPTS overall) inline under their page.
 * Exported for tests; the tool handler wraps it.
 */
export function searchDocsIndex(index: DocsIndexEntry[], rawQuery: string, sectionFilter?: string): string {
  const keywords = toKeywords(rawQuery);
  if (keywords.length === 0) {
    return 'Please provide search terms to find relevant documentation.';
  }

  const candidates = sectionFilter ? index.filter((entry) => entry.section === sectionFilter) : index;
  const hits = scoreSections(candidates, keywords);

  if (hits.length === 0) {
    return index.length === 0
      ? 'Documentation index is not available. The docs search index may need to be rebuilt.'
      : 'No documentation found matching your query. Try different search terms.';
  }

  const pages: DocsIndexEntry[] = [];
  for (const hit of hits) {
    if (!pages.includes(hit.page)) pages.push(hit.page);
    if (pages.length === MAX_PAGES) break;
  }

  const headers = new Map(pages.map((page) => [page, [
    `Title: ${page.title}`,
    `URL: ${pageUrl(page)}`,
    `Description: ${page.description}`,
    `Key Topics: ${keyTopics(page)}`,
  ].join('\n')]));

  const chosen = new Map<DocsIndexEntry, SectionHit[]>(pages.map((page) => [page, []]));
  let chosenCount = 0;
  for (const hit of hits) {
    if (chosenCount === MAX_EXCERPTS) break;
    const forPage = chosen.get(hit.page);
    if (!forPage || forPage.length === MAX_EXCERPTS_PER_PAGE) continue;
    if (!hit.section.text) continue;
    forPage.push(hit);
    chosenCount += 1;
  }

  const headerChars = [...headers.values()].reduce((total, header) => total + header.length, 0)
    + PAGE_SEPARATOR.length * (pages.length - 1);
  let remaining = DOCS_SEARCH_MAX_CHARS - headerChars;

  const blocks = pages.map((page) => {
    const parts = [headers.get(page)!];
    for (const hit of chosen.get(page)!) {
      const label = hit.section.heading || page.title;
      const prefix = `Section: ${label}\nURL: ${pageUrl(page, hit.section.anchor)}\n`;
      const budget = Math.min(MAX_EXCERPT_CHARS, remaining - prefix.length - BLOCK_SEPARATOR.length);
      if (budget < 200) break;
      const text = excerpt(hit.section.text, keywords, budget);
      parts.push(`${prefix}${text}`);
      remaining -= prefix.length + text.length + BLOCK_SEPARATOR.length;
    }
    return parts.join(BLOCK_SEPARATOR);
  });

  return blocks.join(PAGE_SEPARATOR);
}

export function registerDocsTools(aiTools: Map<string, AiTool>): void {
  function registerTool(tool: AiTool): void {
    aiTools.set(tool.definition.name, tool);
  }

  registerTool({
    tier: 1 as AiToolTier,
    domain: 'core',
    searchHint: 'Breeze documentation, how-to guides, feature help and reference material',
    alwaysLoad: true,
    definition: {
      name: 'search_documentation',
      description: 'Search Breeze RMM documentation for how-to guides, feature explanations, and reference material. Use when users ask how to do something, need help understanding a feature, or want to learn about Breeze capabilities.',
      input_schema: {
        type: 'object' as const,
        properties: {
          query: { type: 'string', description: 'Search terms to find relevant documentation' },
          section: {
            type: 'string',
            enum: ['getting-started', 'deploy', 'agents', 'security', 'features', 'monitoring', 'reference'],
            description: 'Optional: filter results to a specific documentation section'
          }
        },
        required: ['query']
      }
    },
    handler: async (input, _auth) => {
      const rawQuery = typeof input.query === 'string' ? input.query : '';
      const sectionFilter = typeof input.section === 'string' ? (input.section as DocsSection) : undefined;
      return searchDocsIndex(typedDocsIndex, rawQuery, sectionFilter);
    }
  });
}
